from openpyxl import load_workbook
from decimal import Decimal
import itertools
from pathlib import Path

src = "/Users/mac/Library/Containers/com.tencent.xinWeChat/Data/Documents/xwechat_files/zhuyexiaosha_1221/msg/file/2026-10/教师书款.xlsx"
target = Decimal('9087.51')

wb = load_workbook(src)

def get_items(ws):
    items=[]
    for r in range(3,106):
        name=(ws.cell(r,1).value or '').strip()
        price=ws.cell(r,3).value
        qty=ws.cell(r,4).value
        if price is None: continue
        price=Decimal(str(price))
        qty=int(qty or 0)
        items.append({'r':r,'name':name,'price':price,'qty':qty,'sub':price*qty,
                      'is_teacher':'教师用书' in name})
    return items

def solve(items, excess, max_abs_delta=5, max_rows_changed=8):
    cands=[]
    for it in items:
        if it['is_teacher']:
            continue
        if it['qty']<=0:
            continue  # don't touch zeros; don't create from zero either? user said don't set to 0
        opts=[]
        # decrease down to 1 only
        for d in range(1, min(max_abs_delta, it['qty']-1)+1):
            opts.append(-d)
        for d in range(1, max_abs_delta+1):
            opts.append(d)
        if opts:
            cands.append((it, opts))

    for k in range(1, max_rows_changed+1):
        for chosen in itertools.combinations(cands, k):
            opt_lists=[opts for _,opts in chosen]
            for deltas in itertools.product(*opt_lists):
                # after change qty must be >=1
                ok=True
                change=Decimal('0')
                for i in range(k):
                    newq=chosen[i][0]['qty']+deltas[i]
                    if newq < 1:
                        ok=False; break
                    change += chosen[i][0]['price']*Decimal(deltas[i])
                if not ok: continue
                if change == -excess:
                    return [(chosen[i][0], deltas[i]) for i in range(k)]
    return None

